\label{def:ft}
For $n\geq1$, the \emph{framed Drinfeld--Kohno Lie algebra} $\mathfrak{ft}_n$ is the completed Lie algebra generated by $T_{ij}=T_{ji}$, $0\leq i,j\leq n-1$, subject to
\begin{equation}\label{eq:ft-relations}
\begin{aligned}
[T_{ij},T_{kl}]&=0 &&\text{for }\{i,j\}\cap\{k,l\}=\varnothing,\\
[T_{ij},T_{ki}+T_{kj}]&=0 &&\text{for distinct }i,j,k,\\
[T_{ii},T_{jk}]&=0 &&\text{for all }i,j,k.
\end{aligned}
\end{equation}
The \emph{Drinfeld--Kohno Lie algebra} $\mathfrak{t}_n$ is generated by $t_{ij}=t_{ji}$, $0\le i\ne j\le n-1$, subject to the first two families of relations. We put
\[
c_n=\sum_{0\le i<j<n}t_{ij}\in\mathfrak{t}_n,\qquad \mathfrak{d}_n=\overline{[\mathfrak{t}_n,\mathfrak{t}_n]}=\mathcal{F}^2\mathfrak{t}_n .
\]

\label{rem:spherical}
Put
\begin{equation}\label{eq:output}
T_{ni}=T_{in}=-\sum_{j<n}T_{ji}\quad(0\le i<n),\qquad T_{nn}=\sum_{i,j<n}T_{ij}=\sum_{i<n}T_{ii}+2\,s(c_n).
\end{equation}
Then $\mathfrak{ft}_n$ is presented by generators $T_{ij}=T_{ji}$, $0\le i,j\le n$, subject to $[T_{ij},T_{kl}]=0$ for $\{i,j\}\cap\{k,l\}=\varnothing$, centrality of every $T_{ii}$, and $\sum_{j=0}^nT_{ij}=0$ for $0\le i\le n$ \cite[\S5.1]{willwacher2024cyclic} (compare \cite[Section5.3]{ihara_braids} and \cite[Definition~3.3]{singh2026cyclic}).

\label{def:grt}
The \emph{graded Grothendieck--Teichm\"uller group} and its Lie algebra are
\[
\begin{gathered}
{\mathsf{GRT}}_1=\bigl\{g\in\exp(\mathcal{F}^3\widehat{\mathfrak{f}}_2):\ g\text{ satisfies (P)}\bigr\},\\
{\mathfrak{grt}}_1=\bigl\{\psi\in\mathcal{F}^3\widehat{\mathfrak{f}}_2:\ \psi\text{ satisfies (P$'$)}\bigr\}.
\end{gathered}
\]

\label{prop:reflection}
Let $n\ge2$.
\begin{enumerate}[label=\textup{(\arabic*)}]
\item For $0<i,j<n$,
\begin{equation}\label{eq:defect}
P_{\rho_n}s(t_{ij})=s F_n(t_{ij}),\qquad P_{\rho_n}s(t_{0j})=sF_n(t_{0j})-T_{n-j,\,n-j},
\end{equation}
where $F_n$ is given by \eqref{eq:intro-flip}.
\item The map $q\,P_{\rho_n}\,s$ is the continuous Lie algebra endomorphism of $\mathfrak{t}_n$ given by \eqref{eq:intro-flip}. Thus $F_n=q\,P_{\rho_n}\,s$ is well defined. It is an involutive automorphism of $\mathfrak{t}_n$, and $F_n(c_n)=-c_n$.
\item $P_{\rho_n}s=sF_n$ on $\mathfrak{d}_n$ and on $\widehat U(\mathfrak{d}_n)$.
\end{enumerate}
